//   with hardware events giving the 8 values of mip.{MSIP/MTIP/MEIP} (8 x 8 bins)
/////////////////////////////////
  CSRSI mstatus, 8   # mstatus.MIE = 1

# Set x13 = 0x000 for mie
  CSRW mie, zero
  LI(x13, 0x000)

  CSRW(mie, zero)
# Testcase: mie: 000, mip: 000
InterruptsSm_cg_cp_priority_mie_000_mip_000:
  CSRW mie, x13
  RVTEST_IDLE_FOR_INTERRUPT(x11)
# Clear and disable interrupts to reset for next testcase
  RVTEST_CLR_MEXT_INT
  # Clear machine timer interrupt
  LI(x11, -1)
// skip clearing interrupt if RVMODEL_MTIMECMP_ADDRESS is not defined
#ifdef RVMODEL_MTIMECMP_ADDRESS
  LA(x10, RVMODEL_MTIMECMP_ADDRESS)
  SREG x11, 0(x10)
#if __riscv_xlen == 32
  sw x11, 4(x10)
#endif
#endif
  RVTEST_CLR_MSW_INT
  CSRW(mie, zero)

  CSRW(mie, zero)
# Testcase: mie: 000, mip: 001
InterruptsSm_cg_cp_priority_mie_000_mip_001:
  RVTEST_SET_MSW_INT
  CSRW mie, x13
  RVTEST_IDLE_FOR_INTERRUPT(x11)
# Clear and disable interrupts to reset for next testcase
  RVTEST_CLR_MEXT_INT
  # Clear machine timer interrupt
  LI(x11, -1)
// skip clearing interrupt if RVMODEL_MTIMECMP_ADDRESS is not defined
#ifdef RVMODEL_MTIMECMP_ADDRESS
  LA(x10, RVMODEL_MTIMECMP_ADDRESS)
  SREG x11, 0(x10)
#if __riscv_xlen == 32
  sw x11, 4(x10)
#endif
#endif
  RVTEST_CLR_MSW_INT
  CSRW(mie, zero)

  CSRW(mie, zero)
# Testcase: mie: 000, mip: 010
InterruptsSm_cg_cp_priority_mie_000_mip_010:
  # Cause machine timer interrupt if supported
#ifdef RVMODEL_MTIME_ADDRESS
  LA(x12, RVMODEL_MTIME_ADDRESS)
  LA(x10, RVMODEL_MTIMECMP_ADDRESS)
#if __riscv_xlen == 64
  LREG x11, 0(x12)
  SREG x11, 0(x10)
#elif __riscv_xlen == 32
# Write sequence to prevent spurious interrupts
# Read mtime (new comparand will be in temp2:temp)
  lw x11, 0(x12) # mtime[31:0] -> low word
  lw x8, 4(x12) # mtime[63:32] -> high word
# 3-step write sequence (new comparand is in temp2:temp)
  LI(x12, -1) # Reuse r_mtime for -1
  sw x12, 0(x10) # Step 1: Write -1 to low (no smaller than old)
  sw x8, 4(x10) # Step 2: Write high word (no smaller than new)
  sw x11, 0(x10) # Step 3: Write low word (new value)
#endif
#endif
  CSRW mie, x13
  RVTEST_IDLE_FOR_INTERRUPT(x11)
# Clear and disable interrupts to reset for next testcase
  RVTEST_CLR_MEXT_INT
  # Clear machine timer interrupt
  LI(x11, -1)
// skip clearing interrupt if RVMODEL_MTIMECMP_ADDRESS is not defined
#ifdef RVMODEL_MTIMECMP_ADDRESS
  LA(x10, RVMODEL_MTIMECMP_ADDRESS)
  SREG x11, 0(x10)
#if __riscv_xlen == 32
  sw x11, 4(x10)
#endif
#endif
  RVTEST_CLR_MSW_INT
  CSRW(mie, zero)

  CSRW(mie, zero)
